    category: 'sedes',
    sourceName: 'Wikipedia / FIFA',
    sourceUrl: 'https://en.wikipedia.org/wiki/SoFi_Stadium',
    sourceLang: 'es',
    publishedAt: '2026-06-03T17:00:00Z',
